import numpy as np
from rdkit import Chem
m=Chem.MolFromMolFile('structure.mol',removeHs=False); x=np.array(m.GetConformer().GetPositions());
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx(); d=np.linalg.norm(x[i]-x[j]);
 if d>2.6 or d<.90: print('bad bond',i,j,d)
print('Ir-Cp',np.linalg.norm(x[[59,60,62,64,66]]-x[26],axis=1))
print('core bonds')
for i,j in [(12,13),(12,28),(13,26),(28,26),(28,29),(28,30),(26,27),(12,11)]:print(i,j,np.linalg.norm(x[i]-x[j]))
D=Chem.GetDistanceMatrix(m)
for i in range(len(x)):
 for j in range(i):
  d=np.linalg.norm(x[i]-x[j]);
  if D[i,j]>2 and d<1.6 and 26 not in [i,j]: print('contact',i,m.GetAtomWithIdx(i).GetSymbol(),j,m.GetAtomWithIdx(j).GetSymbol(),d)
# overview render
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig=plt.figure(figsize=(10,10));ax=fig.add_subplot(projection='3d')
colors={'C':'gray','H':'white','N':'blue','P':'orange','Cl':'green','Ge':'purple','Ir':'brown'}
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();ax.plot(*x[[i,j]].T,color='gray',lw=1.5)
for j in [59,60,62,64,66]:ax.plot(*x[[26,j]].T,color='brown',lw=.8,alpha=.7)
for a,p in zip(m.GetAtoms(),x):
 sym=a.GetSymbol();ax.scatter(*p,c=colors[sym],s=65 if sym!='H' else 12,edgecolors='k',linewidths=.3)
 if sym not in ['C','H']:ax.text(*p,sym,fontsize=12)
ax.view_init(25,65);ax.set_box_aspect([1,1,1]);plt.savefig('check.png',dpi=140)
